    // --- Mock scoring bands -----------------------------------------------------

    @Test
    void uncertainNotesScoreLow() {
        OpenAiEvaluationService service = newMockService();
        PageDto pythagoras = new PageDto("pg-pythagoras", "nb-math", null,
                "Pythagorean Theorem",
                "Formula is a2 + b2 = c2 or was it a + b = c2? Not sure which side is which. "
